window.inventoryItemUi = (() => {
  const esc=accountEscape,dialog=document.createElement('dialog');
  dialog.className='inventory-item-dialog';dialog.setAttribute('aria-labelledby','inventory-item-title');document.body.append(dialog);
  let selectedId=null,owner=null,returnId=null,imageIndex=0;
  const title=item=>t(item.title,item.titleDe||item.title),estimate=item=>item.estimatedValueTokens??item.sellValue??item.price??0;
  const startingPrice=item=>Math.max(1,Math.round(estimate(item)*.7));
  const stateLabel=item=>item.storeId?t('In a store','Im Laden'):item.listed?t('Listed','Angeboten'):t('Available','Verfügbar');
  const rarity=item=>esc(rarityLabel(item.rarity||item.caseTier||'common'));
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${name==='list'?'<path d="m13 3 8 8-4 4-8-8 4-4Zm-4 4L5 11l4 4 4-4m-2 2-8 8M15 21h7"/>':name==='case'?'<path d="m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4m-9 4v10"/>':'<path d="M4 12h16m-6-6 6 6-6 6"/>'}</svg>`;
  function photos(item){return [...new Set([item.image,...(Array.isArray(item.images)?item.images:[])].filter(value=>typeof value==='string'&&value))].slice(0,8);}
  function art(item,detail=false){const image=photos(item)[detail?imageIndex:0];return item.kind==='case'?`<div class="inventory-case-art">${caseArtwork(item)}</div>`:image?`<img src="${esc(image)}" alt="${detail?esc(title(item)):''}" ${detail?'':'loading="lazy"'} referrerpolicy="no-referrer">`:`<div class="inventory-no-image" aria-hidden="true">${icon('case')}</div>`;}
  function quickButton(item,primary=false){return `<button type="button" class="${primary?'primary-button':'inventory-quick-list'}" data-economy="quick-list" data-id="${esc(item.id)}" data-price="${startingPrice(item)}" aria-label="${esc(t(`Quick list one ${title(item)} at ${justizEuro(startingPrice(item))} for 15 minutes`,`Ein Exemplar von ${title(item)} für 15 Minuten ab ${justizEuro(startingPrice(item))} anbieten`))}">${icon('list')}<span>${t('Quick list','Schnell anbieten')} · ${justizEuro(startingPrice(item))}</span></button>`;}
  function card(item){
    const copies=item.copies||[item],available=copies.filter(copy=>!copy.listed&&!copy.storeId),focus=new URLSearchParams(location.search).get('focus');
    const chosen=available.find(copy=>copy.id===focus)||available[0]||copies.find(copy=>copy.id===focus)||item,isCase=item.kind==='case';
    return `<article class="collection-item inventory-find ${isCase?'sealed-case-item ':''}rarity-${esc(item.rarity||item.caseTier||'common')}${copies.some(copy=>copy.id===focus)?' is-highlighted':''}" data-inventory-card="${esc(chosen.id)}"><button type="button" class="inventory-card-trigger" data-inventory-detail="${esc(chosen.id)}" aria-haspopup="dialog" aria-label="${esc(t(`View details: ${title(item)}`,`Details ansehen: ${title(item)}`))}"></button><div class="inventory-find-media">${art(item)}<span class="inventory-rarity rarity-label">${isCase?t('Sealed case','Versiegelte Kiste'):rarity(item)}</span>${copies.length>1?`<span class="inventory-copy-count item-count" aria-label="${number(copies.length)} ${t('copies','Exemplare')}">×${copies.length}</span>`:''}</div><div class="inventory-find-copy"><p class="inventory-item-category">${inventoryCategoryLabel(inventoryCategory(item))}</p><h3>${esc(title(item))}</h3><div class="inventory-card-value"><div class="inventory-price-line"><strong>${justizEuro(estimate(item))}</strong>${!isCase?window.marketTrendUi?.markup(item.marketCategory)||'':''}</div><small>${t('Market estimate','Marktschätzung')}</small></div><span class="inventory-state ${item.listed?'is-listed':item.storeId?'is-stocked':'is-available'}">${stateLabel(item)}</span></div><footer class="inventory-find-footer">${available.length?(isCase?`<button class="inventory-open-case" type="button" data-account="open-inventory-case" data-id="${esc(chosen.id)}">${icon('case')}<span>${t('Open case','Kiste öffnen')}</span></button>`:economyFlags.resales?quickButton(chosen):`<button class="inventory-quick-list" type="button" data-account="sell" data-id="${esc(chosen.id)}">${t('Sell','Verkaufen')} · ${justizEuro(chosen.sellValue)}</button>`):`<span class="inventory-card-details">${t('View details','Details ansehen')}${icon('arrow')}</span>`}${available.length&&!isCase&&economyFlags.resales?`<small>${t('1 item · 15 min','1 Artikel · 15 Min')}</small>`:''}</footer></article>`;
  }
  function snapshot(){const item=accountItems.find(entry=>entry.id===selectedId);if(!item)return null;const group=groupedInventory(accountItems).find(entry=>entry.copies.some(copy=>copy.id===item.id));return {item,copies:group?.copies||[item]};}
  function paint(){
    const snapshotData=snapshot();if(!snapshotData){stop();return;}
    const {item,copies}=snapshotData,isCase=item.kind==='case',available=!item.listed&&!item.storeId,images=photos(item);imageIndex=Math.min(imageIndex,Math.max(0,images.length-1));
    const hadFocus=dialog.contains(document.activeElement);
    const expanded=[...dialog.querySelectorAll('details[open]')].map(entry=>entry.dataset.itemSection),focused=document.activeElement?.closest('button')?.dataset.inventoryImage;
    const acquired=item.acquisitionCost==null?t('Unknown','Unbekannt'):justizEuro(item.acquisitionCost);
    const source=({reward:t('Daily reward','Daily-Belohnung'),purchase:t('Purchased','Gekauft'),mischief:t('Stolen item','Gestohlener Artikel'),unknown:t('Not recorded','Nicht erfasst')})[item.acquisitionSource]||t('Not recorded','Nicht erfasst');
    const facts=[[t('Acquisition cost','Anschaffungskosten'),acquired],[t('Acquisition source','Herkunft'),source],...(!isCase?[[t('Historical auction value','Historischer Auktionswert'),euro(item.price)]]:[]),...(item.marketIndex!=null?[[t('Market vs. normal','Markt gegenüber normal'),`${item.marketIndex>=100?'+':''}${number(item.marketIndex-100,1)}%`]]:[])];
    dialog.innerHTML=`<header class="inventory-detail-heading"><p class="eyebrow">${t('YOUR INVENTORY','DEIN INVENTAR')}</p><button type="button" class="dialog-close" data-inventory-close aria-label="${t('Close','Schließen')}">×</button></header><div class="inventory-detail-layout"><section class="inventory-detail-media rarity-${esc(item.rarity||item.caseTier||'common')}" aria-label="${t('Item pictures','Artikelbilder')}"><div class="inventory-detail-image">${art(item,true)}</div>${!isCase&&images.length>1?`<div class="inventory-image-picker" role="group" aria-label="${t('Choose an image','Bild auswählen')}">${images.map((image,n)=>`<button type="button" data-inventory-image="${n}" aria-label="${t('Image','Bild')} ${n+1}" aria-pressed="${n===imageIndex}"><img src="${esc(image)}" alt="" loading="lazy" referrerpolicy="no-referrer"></button>`).join('')}</div>`:''}<p>${isCase?t('One mystery item inside. Contents stay hidden until opened.','Ein geheimer Gegenstand darin. Der Inhalt bleibt bis zum Öffnen verborgen.'):`${rarity(item)} · ${inventoryCategoryLabel(inventoryCategory(item))}`}</p></section><section class="inventory-detail-main"><div class="inventory-detail-tags"><span class="inventory-state ${item.listed?'is-listed':item.storeId?'is-stocked':'is-available'}">${stateLabel(item)}</span>${copies.length>1?`<span>${number(copies.length)} ${t('copies','Exemplare')}</span>`:''}</div><h2 id="inventory-item-title" tabindex="-1">${esc(title(item))}</h2><div class="inventory-detail-value"><span>${t('Estimated market value','Geschätzter Marktwert')}</span><strong>${justizEuro(estimate(item))}</strong>${!isCase?window.marketTrendUi?.markup(item.marketCategory)||'':''}<small>${t('Per item · the final selling price can differ.','Pro Artikel · der endgültige Verkaufspreis kann abweichen.')}</small></div><div class="inventory-detail-actions">${available?`${isCase?`<button type="button" class="primary-button" data-account="open-inventory-case" data-id="${esc(item.id)}">${icon('case')}${t('Open case','Kiste öffnen')}</button>`:''}${economyFlags.resales?`${quickButton(item,!isCase)}<p class="inventory-quick-note">${t('Lists one copy for 15 minutes.','Bietet ein Exemplar für 15 Minuten an.')}</p><button type="button" class="secondary-button" data-economy="list" data-id="${esc(item.id)}">${t('Set price, quantity & duration','Preis, Anzahl & Dauer festlegen')}</button>`:!isCase?`<button type="button" class="primary-button" data-account="sell" data-id="${esc(item.id)}">${t('Sell','Verkaufen')} · ${justizEuro(item.sellValue)}</button>`:''}`:traderItemActions(item,copies)}</div><div class="inventory-detail-sections"><details data-item-section="valuation"><summary>${t('Value & acquisition','Wert & Anschaffung')}</summary><dl>${facts.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>${economyFlags.market&&item.marketCategory?`<a href="/market?category=${encodeURIComponent(item.marketCategory)}" data-page>${t('Market Trends','Markttrends')} ↗</a>`:''}</details>${!isCase?`<details data-item-section="about"><summary>${t('About this item','Über diesen Artikel')}</summary><p>${esc(item.description||t('No further description is saved for this item.','Für diesen Artikel ist keine weitere Beschreibung gespeichert.'))}</p>${item.condition?`<p>${t('Condition','Zustand')}: ${esc(listingLabel(item.condition))}</p>`:''}${item.fulfillment?`<p>${t('Original delivery method','Ursprüngliche Lieferung')}: ${esc(listingLabel(item.fulfillment))}</p>`:''}</details>`:''}${available?`<details data-item-section="manage"><summary>${t('Keep or stock a store','Behalten oder einen Laden beliefern')}</summary>${traderItemActions(item,copies).replace(/<button class="primary-button" data-economy="list"[\s\S]*?<\/button>/,'')}</details>`:''}</div></section></div>`;
    expanded.forEach(id=>{const node=dialog.querySelector(`[data-item-section="${id}"]`);if(node)node.open=true;});
    if(focused!==undefined)dialog.querySelector(`[data-inventory-image="${focused}"]`)?.focus({preventScroll:true});
    else if(hadFocus)dialog.querySelector('h2')?.focus({preventScroll:true});
  }
  function open(id){if(currentAccountPage!=='/inventory'||!account||!accountItems.some(item=>item.id===id))return;selectedId=id;returnId=id;owner=account.id;imageIndex=0;dialog.innerHTML='';paint();if(!dialog.open)dialog.showModal();dialog.querySelector('h2')?.focus({preventScroll:true});}
  function focus(id){const node=accountContent.querySelector(`[data-inventory-detail="${CSS.escape(id||'')}"]`)||accountContent.querySelector('h1');node?.focus({preventScroll:true});}
  function stop(){selectedId=null;owner=null;dialog.close();}
  function refresh(){if(!dialog.open)return;if(account?.id!==owner||currentAccountPage!=='/inventory'){stop();return;}paint();}
  dialog.addEventListener('close',()=>{selectedId=null;owner=null;if(currentAccountPage==='/inventory'&&!document.querySelector('dialog[open]'))focus(returnId);});
  document.addEventListener('click',event=>{
    const close=event.target.closest('[data-inventory-close]');if(close){dialog.close();return;}
    const trigger=event.target.closest('[data-inventory-detail]');if(trigger){open(trigger.dataset.inventoryDetail);return;}
    const image=event.target.closest('[data-inventory-image]');if(image&&dialog.open){imageIndex=Number(image.dataset.inventoryImage);paint();return;}
    if(dialog.open&&dialog.contains(event.target)&&event.target.closest('[data-economy="list"],[data-trader],[data-account="open-inventory-case"],[data-account="sell"]'))dialog.close();
  });
  document.addEventListener('jg:language',()=>refresh());
  function accountChanged(user){if(dialog.open&&(user?.id!==owner||user?.justice?.jailed))stop();}
  return {card,open,stop,refresh,focus,accountChanged};
})();
